// Helpers 21: Link.
func (h dtogen) clone21(v Link) Link {
	out := v
	out.Value = h.clone22(v.Value)
	return out
}
func (h dtogen) equal21(v, w Link) bool {
	if !h.equal22(v.Value, w.Value) {
		return false
	}
	return true
}
func (h dtogen) check21(v Link, b *dtogenCodec.Budget, d, cap int) (err error) {
	count := 1
	if err := b.CheckMap(count, d, cap); err != nil {
		return err
	}
	if err := b.CheckString("v", d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Value: %w", err)
	}
	if err := h.check22(v.Value, b, d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Value: %w", err)
	}
	return nil
}
func (h dtogen) append21(out []byte, v Link) []byte {
	count := 1
	out = dtogenCBOR.AppendMapHeader(out, uint64(count))
	out = dtogenCBOR.AppendText(out, "v")
	out = h.append22(out, v.Value)
	return out
}
func (h dtogen) read21(r *dtogenCodec.Reader, d, cap int) (v Link, err error) {
	count, err := r.Map(d, cap)
	if err != nil {
		return v, err
	}
	previous := ""
	var seen [1]bool
	for i := 0; i < count; i++ {
		key, err := r.String(d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		// Strict canonical key ordering also rejects duplicates before assignment can overwrite them.
		if i > 0 && (len(key) < len(previous) || (len(key) == len(previous) && key <= previous)) {
			return v, dtogenCodec.ErrInvalidData
		}
		previous = key
		switch key {
		case "v":
			seen[0] = true
			v.Value, err = h.read22(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Value: %w", err)
			}
		default:
			return v, dtogenCodec.ErrInvalidData
		}
	}
	if !seen[0] {
		return v, dtogenCodec.ErrInvalidData
	}
	return v, nil
}

