func (h dtogen) check26(v map[string][]*CIDAlias, b *dtogenCodec.Budget, d, cap int) (err error) {
	if err := b.CheckMap(len(v), d, cap); err != nil {
		return err
	}
	for k, x := range v {
		if err := h.check8(k, b, d+1, int(^uint(0)>>1)); err != nil {
			return err
		}
		if err := h.check27(x, b, d+1, int(^uint(0)>>1)); err != nil {
			return err
		}
	}
	return nil
}
func (h dtogen) append26(out []byte, v map[string][]*CIDAlias) []byte {
	keys := make([]string, 0, len(v))
	for k := range v {
		keys = append(keys, k)
	}
	dtogenSlices.SortFunc(keys, func(a, b string) int {
		if len(a) != len(b) {
			return len(a) - len(b)
		}
		if a < b {
			return -1
		}
		if a > b {
			return 1
		}
		return 0
	})
	out = dtogenCBOR.AppendMapHeader(out, uint64(len(v)))
	for _, k := range keys {
		out = dtogenCBOR.AppendText(out, string(k))
		out = h.append27(out, v[k])
	}
	return out
}
func (h dtogen) read26(r *dtogenCodec.Reader, d, cap int) (v map[string][]*CIDAlias, err error) {
	count, err := r.Map(d, cap)
	if err != nil {
		return v, err
	}
	v = make(map[string][]*CIDAlias, count)
	previous := ""
	for i := 0; i < count; i++ {
		k, err := h.read8(r, d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		key := string(k)
		// Strict canonical key ordering also rejects duplicates before assignment can overwrite them.
		if i > 0 && (len(key) < len(previous) || (len(key) == len(previous) && key <= previous)) {
			return v, dtogenCodec.ErrInvalidData
		}
		previous = key
		x, err := h.read27(r, d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		v[k] = x
	}
	return v, nil
}

